  '</style></head><body><div class="wrap">' +
  '<div class="hero"><h1>' + escapeHtml(META.uiHeading || "Docker Updates - UI (Hardening Test)") + '</h1><p>' + escapeHtml(META.uiSubtitle || data.tailscaleNote) + (META.uiSubtitle ? ' · ' + escapeHtml(data.tailscaleNote) : '') + '</p></div>' +
